set
  title = 'Introduction to Criminal Justice',
  goal = 'Introduction to Criminal Justice',
  summary = 'Introduction to Criminal Justice treats the field as linked institutions, decisions, values, and consequences. Students trace U.S. history, constitutional foundations, crime measurement, and criminological theory, then study policing, courts, corrections, victims, youth development, inequality, policy, ethics, evidence, technology, comparative and public health approaches, careers, and evidence-based reform.',
  data = $icjjson${"slug": "introduction-to-criminal-justice", "title": "Introduction to Criminal Justice", "description": "Introduction to Criminal Justice treats the field as linked institutions, decisions, values, and consequences. Students trace U.S. history, constitutional foundations, crime measurement, and criminological theory, then study policing, courts, corrections, victims, youth development, inequality, policy, ethics, evidence, technology, comparative and public health approaches, careers, and evidence-based reform.", "topics": [{"id": "97f3c917-bf22-457c-adb4-f62380d5c9ff", "type": "topic", "title": "Criminal Justice System, Core Concepts, and System Flow", "description": "Introduce criminal justice as a set of linked institutions, decisions, values, and consequences rather than a simple sequence of agencies.", "children": [{"id": "d9c0ff0a-a16e-406e-a2f5-78b85fde2340", "type": "subtopic", "title": "System components", "children": [{"id": "31661723-444f-44d5-8e4a-c84e1f851917", "type": "concept", "title": "Police"}, {"id": "cf3f07bb-8e17-4aea-bc36-39a569936392", "type": "concept", "title": "Courts"}, {"id": "19417872-3475-453d-b0e8-533ad32e58a5", "type": "concept", "title": "Corrections"}, {"id": "5050367e-cd14-4ff1-b3c2-1c018870d694", "type": "concept", "title": "Community and social services"}], "description": "Students begin by seeing criminal justice as an ecosystem of institutions whose decisions affect one another."}, {"id": "e9a62383-e79f-44e0-b932-9a577bf7cecc", "type": "subtopic", "title": "Case flow", "children": [{"id": "5e4b01ed-71b8-449f-9339-9ce0cf354055", "type": "concept", "title": "Reporting and investigation"}, {"id": "6434a989-5f21-4b2c-b202-32c1e7c09b94", "type": "concept", "title": "Arrest and charging"}, {"id": "bb90787e-6143-452c-a27e-760d675fa53c", "type": "concept", "title": "Adjudication"}, {"id": "d23d7fd4-4bcd-4ff4-9175-2494abd088b1", "type": "concept", "title": "Sentencing and supervision"}], "description": "Case flow shows how a reported incident can become an arrest, charge, plea, sentence, appeal, or diversion."}, {"id": "caa63cd5-c419-4052-a161-f1c750288063", "type": "subtopic", "title": "Core vocabulary", "children": [{"id": "42a019ac-2b65-4cae-b244-0b04f800120a", "type": "concept", "title": "Crime vs deviance"}, {"id": "a2424d6b-4da0-45e2-bf29-c491cf063981", "type": "concept", "title": "Felony vs misdemeanor"}, {"id": "0dee5a32-ab49-487b-ba60-6c1b79a87cff", "type": "concept", "title": "Discretion"}, {"id": "0e1a050f-2a3b-4fe8-bc29-ab99acedb415", "type": "concept", "title": "Legitimacy"}], "description": "Shared language prevents confusion when students move from news accounts to legal and empirical analysis."}]}, {"id": "99a90236-8cf3-40a0-82f0-035f8f1c6728", "type": "topic", "title": "History of Criminal Justice in the United States", "description": "Trace how American criminal justice developed through policing, courts, punishment, constitutional law, race, reform, and political change.", "children": [{"id": "6e8187d4-fdc6-4058-92c3-a98e42ebc2db", "type": "subtopic", "title": "Early American justice", "children": [{"id": "f08c5e97-4ad9-471b-a9dd-023255f998bb", "type": "concept", "title": "Colonial law enforcement"}, {"id": "55e611aa-916c-4164-ad70-62c5fd7ed0b3", "type": "concept", "title": "Slave patrols and racial control"}, {"id": "cee68bbd-9753-482c-8093-6acc49dfccfd", "type": "concept", "title": "Local courts"}, {"id": "4e094807-af98-4f15-9954-2fcf717339f9", "type": "concept", "title": "Early jails and prisons"}], "description": "Historical foundations show that modern institutions grew from local, racial, economic, and political arrangements."}, {"id": "84bd1493-d96a-4331-b82c-35aa3ef6fc1b", "type": "subtopic", "title": "Professionalization and reform", "children": [{"id": "2cbd2c50-1b3b-4e4e-a5a4-ace3474f3df0", "type": "concept", "title": "Police professional model"}, {"id": "a840b2b2-70de-4a1c-9e42-b24df6b2f17c", "type": "concept", "title": "Progressive era reform"}, {"id": "a2fa3738-bf72-4969-a6f8-c36a1169e75c", "type": "concept", "title": "Prison reform"}, {"id": "645fd25e-40f5-4955-89de-39ae0ae3deeb", "type": "concept", "title": "Due process revolution"}], "description": "Modern agencies developed through waves of professionalization, bureaucratization, and reform."}, {"id": "e1a4a5ef-6501-409c-8951-5d16b49feb0c", "type": "subtopic", "title": "Late twentieth-century change", "children": [{"id": "3e89259d-7137-4d4e-ac93-6101a226ede6", "type": "concept", "title": "War on drugs"}, {"id": "5459b5bd-0de1-479f-9328-f3e80a7bce91", "type": "concept", "title": "Mass incarceration"}, {"id": "42da800b-6818-41cf-a585-e9cf1c5d4caf", "type": "concept", "title": "Victims' rights movement"}, {"id": "607861b0-a966-4425-8dc9-bdb0059b3ac1", "type": "concept", "title": "Community policing and reentry reform"}], "description": "Contemporary debates are rooted in policy shifts around crime, drugs, punishment, victims, and rights."}]}, {"id": "4e0559b6-1d15-46c2-96f1-a715511ad043", "type": "topic", "title": "Law, Constitutional Foundations, and Due Process", "description": "Build the legal vocabulary needed to understand rights, authority, procedure, and limits on state power.", "children": [{"id": "e9c166c2-cbbb-4ab7-96bd-f85092f6e075", "type": "subtopic", "title": "Sources of criminal law", "children": [{"id": "5b9657f2-20f2-4095-a55d-5386627ffa98", "type": "concept", "title": "Constitutions"}, {"id": "22f2a0c3-e447-4d28-b60d-3f723f8fb306", "type": "concept", "title": "Statutes"}, {"id": "d567359e-c861-4e54-9ad9-8d6e472078f9", "type": "concept", "title": "Cases"}, {"id": "52ad2803-fe6e-4d39-b8bb-553f5c148bca", "type": "concept", "title": "Administrative rules and policies"}], "description": "Students need to know where criminal justice authority comes from and how it is constrained."}, {"id": "a0b47214-5230-4bb6-9b0d-5b5bc42019e1", "type": "subtopic", "title": "Constitutional protections", "children": [{"id": "70b7801d-a593-4628-939c-f582cf79fe96", "type": "concept", "title": "Fourth Amendment"}, {"id": "a21724c7-9664-480d-a397-989141194fcb", "type": "concept", "title": "Fifth Amendment"}, {"id": "3e288026-6938-4e38-b9c0-e1c8b5b739e7", "type": "concept", "title": "Sixth Amendment"}, {"id": "53a21678-5a21-4f69-b65e-8484beb70cbb", "type": "concept", "title": "Eighth Amendment"}], "description": "Constitutional law defines key limits on policing, courts, punishment, and state power."}, {"id": "b69bd459-96d4-481e-8cf7-972cbd589ec4", "type": "subtopic", "title": "Due process and crime control models", "children": [{"id": "acc15fcd-be44-4ab1-8a1e-9b1a0abcd7fc", "type": "concept", "title": "Accuracy vs efficiency"}, {"id": "59c06713-8a1f-47a8-9b66-d629e9a16ffa", "type": "concept", "title": "Individual rights"}, {"id": "02586069-eabd-4d60-93d1-b460157fe0fe", "type": "concept", "title": "Public safety"}, {"id": "585dc4ec-9c2a-472f-9db5-68594488b556", "type": "concept", "title": "Procedural fairness"}], "description": "The due process and crime control models help students analyze recurring tensions in justice policy."}]}, {"id": "1d0dac09-9b7e-4141-9b71-d5f83188a093", "type": "topic", "title": "Crime Measurement, Data Literacy, and Justice Statistics", "description": "Learn how crime, victimization, arrests, courts, corrections, and public safety are measured and mismeasured.", "children": [{"id": "59dda196-3ed0-4c57-ac02-dbce32923884", "type": "subtopic", "title": "Official crime data", "children": [{"id": "f7e8e105-361c-455b-9d6b-b0d97ceb2dbf", "type": "concept", "title": "UCR and NIBRS"}, {"id": "92568d6c-217c-4017-882b-76e6fee9eab3", "type": "concept", "title": "FBI Crime Data Explorer"}, {"id": "b88b6169-1db3-4998-b83b-0884d00db84d", "type": "concept", "title": "Arrest data"}, {"id": "f5f1a0f9-c2ba-4a11-8ffb-17128e9e2ae1", "type": "concept", "title": "Clearance rates"}], "description": "Crime data are essential, but they reflect reporting practices, definitions, and institutional choices."}, {"id": "64ed651b-8016-49d6-9db7-1ea5815d737b", "type": "subtopic", "title": "Victimization and self-report data", "children": [{"id": "628dad97-7ea5-42c1-b394-9e759eba9877", "type": "concept", "title": "NCVS"}, {"id": "6424e936-36b0-4172-bd8e-275e111d87f2", "type": "concept", "title": "Self-report surveys"}, {"id": "3d31504a-bbf0-4f34-a829-be1873b7ec8e", "type": "concept", "title": "Dark figure of crime"}, {"id": "fc0ca592-9392-40a5-a337-a52e8689f3f9", "type": "concept", "title": "Reporting behavior"}], "description": "Alternative data sources reveal crime that may not appear in police records."}, {"id": "72f55502-2a45-4e39-ac60-b7282ee60617", "type": "subtopic", "title": "Interpreting justice statistics", "children": [{"id": "8f6a8a0d-4c82-4505-bba7-b4b75799e098", "type": "concept", "title": "Rates vs counts"}, {"id": "d2cd58e6-8076-43f0-b8d6-c66993a599ff", "type": "concept", "title": "Trends and baselines"}, {"id": "36440ed7-c3ae-428d-94fd-c8b49f44bc49", "type": "concept", "title": "Disaggregation"}, {"id": "ccb2ed70-bb0b-4801-a387-bbc669ae79f6", "type": "concept", "title": "Correlation vs causation"}], "description": "Students learn to read data carefully before drawing policy conclusions."}]}, {"id": "5d527bd2-5341-431d-8573-f8f4af7a7b5c", "type": "topic", "title": "Criminological Theory and Crime Causation Overview", "description": "Use major theories of crime to connect individual behavior, social context, institutions, opportunity, and policy choices.", "children": [{"id": "9fde2f55-c7dc-4ac5-80da-e070e9bfb5fe", "type": "subtopic", "title": "Classical and deterrence perspectives", "children": [{"id": "3e439b2c-49c2-4a72-a3c9-f1bace8eb946", "type": "concept", "title": "Rational choice"}, {"id": "9654346e-2e5f-4a7a-8b94-93c0cdd89061", "type": "concept", "title": "Deterrence"}, {"id": "0d305267-ff49-4f77-b477-0e4261c08a1f", "type": "concept", "title": "Routine activities"}, {"id": "1bfcddf4-6558-4015-b89e-0d7c1300054c", "type": "concept", "title": "Situational prevention"}], "description": "Classical theory links behavior to choice, punishment, certainty, severity, and swiftness."}, {"id": "a1d45879-48d6-40c7-8709-b0649fd34d00", "type": "subtopic", "title": "Biological and psychological perspectives", "children": [{"id": "988e10dd-187a-4dce-b163-ffbc3e3516c2", "type": "concept", "title": "Development"}, {"id": "2780473a-a78e-43e9-938d-949284f3a2b8", "type": "concept", "title": "Mental health"}, {"id": "e892e7be-976c-4895-91a4-8abe950f47af", "type": "concept", "title": "Trauma"}, {"id": "f002e272-090b-47b6-bfb9-6b8d9d424ffd", "type": "concept", "title": "Neuropsychological risk factors"}], "description": "Individual-level theories help explain risk factors while raising ethical cautions about determinism."}, {"id": "3d17168b-d529-4854-84ab-006cda8d8626", "type": "subtopic", "title": "Social and critical perspectives", "children": [{"id": "ecf73413-4dca-4894-a899-02b4abc16570", "type": "concept", "title": "Social disorganization"}, {"id": "f697bb54-fdf8-4092-a600-552a43e5f69f", "type": "concept", "title": "Strain"}, {"id": "7be9b2e4-7f40-4c15-ba9e-795dfb4b64a4", "type": "concept", "title": "Differential association"}, {"id": "4f20ddf2-704f-455f-bca9-df66d42416a3", "type": "concept", "title": "Conflict and critical theory"}], "description": "Social theories connect crime to neighborhoods, inequality, learning, institutions, and power."}]}, {"id": "c3a1523d-2798-43e0-bb2a-0c1e9b28cb51", "type": "topic", "title": "Policing in America", "description": "Study police roles, discretion, organization, investigation, use of force, accountability, and community relationships.", "children": [{"id": "d24ac47e-6ee6-4662-8307-8aab102ea9f3", "type": "subtopic", "title": "Police roles and organization", "children": [{"id": "6e29ad14-e1fd-427d-9b64-566bd1488777", "type": "concept", "title": "Municipal police"}, {"id": "c366848b-ca98-4350-b813-3d9992782b03", "type": "concept", "title": "County sheriffs"}, {"id": "c3f1080d-c56d-42f1-a57e-e625f2383dfa", "type": "concept", "title": "State police"}, {"id": "12058cd2-a5a5-459e-9374-9c482abce9ce", "type": "concept", "title": "Federal law enforcement"}], "description": "Policing includes patrol, response, investigation, service, prevention, order maintenance, and emergency work."}, {"id": "b0809585-323e-47a3-80ff-4c59858697fd", "type": "subtopic", "title": "Discretion, use of force, and accountability", "children": [{"id": "e171650c-faa9-4b09-8399-23cc2812f0df", "type": "concept", "title": "Stops and searches"}, {"id": "ad9a3a32-fcb3-4414-bfa2-324d6021c150", "type": "concept", "title": "Use-of-force continuum"}, {"id": "e4035233-7e5a-4810-922e-1504050b71bd", "type": "concept", "title": "Body-worn cameras"}, {"id": "62fa2a7a-fdf8-4d6a-83dc-81a04a56b22f", "type": "concept", "title": "Civilian oversight"}], "description": "Police decisions are highly consequential because they are often made quickly and with limited information."}, {"id": "edf9808c-9ccb-4752-a397-6695162b201d", "type": "subtopic", "title": "Community policing and legitimacy", "children": [{"id": "57cc5ae2-9450-4eb0-9271-481a7a9142f4", "type": "concept", "title": "Problem-oriented policing"}, {"id": "2123c6ff-3c30-4756-a7fb-d21dbf27950f", "type": "concept", "title": "Community partnerships"}, {"id": "3339e1d3-38d2-4169-8560-f972b3f6e325", "type": "concept", "title": "Procedural justice"}, {"id": "f2e87e48-fe3d-418f-be8a-97036a558522", "type": "concept", "title": "Police-community relations"}], "description": "Police effectiveness depends partly on public trust, procedural justice, and community relationships."}]}, {"id": "5a742f49-98bc-4f94-97d0-3e9dbe2e1c70", "type": "topic", "title": "Courts, Prosecution, Defense, and Adjudication", "description": "Follow cases through courts while examining prosecutors, defense counsel, judges, juries, pleas, trials, and sentencing.", "children": [{"id": "3563dffc-25cc-4f86-8842-f4a89502ea47", "type": "subtopic", "title": "Court structure and actors", "children": [{"id": "9ed711ef-3e60-4e3d-b5be-0f351ed8f946", "type": "concept", "title": "Judges"}, {"id": "b9f5697b-db41-45c8-ad35-edd126c5d682", "type": "concept", "title": "Prosecutors"}, {"id": "3ae0639a-2283-4ea5-809d-e325d2065a66", "type": "concept", "title": "Defense counsel"}, {"id": "497dc293-a585-4300-a182-44a64c0ead5b", "type": "concept", "title": "Court staff and juries"}], "description": "Courts translate arrests and charges into legal decisions through roles with different duties and incentives."}, {"id": "e20fa241-2c5e-4495-a579-6e0836c5de12", "type": "subtopic", "title": "Pretrial and plea bargaining", "children": [{"id": "3eda172a-a6bd-4dc3-8cfa-f9169d48f7c6", "type": "concept", "title": "Bail and detention"}, {"id": "d457b00b-3bb9-419f-a886-b13fc827b93b", "type": "concept", "title": "Charging"}, {"id": "22e0351a-45d8-4add-a345-8473666ea167", "type": "concept", "title": "Plea negotiation"}, {"id": "b24e3f6f-4d39-48e1-b56b-1172303389a6", "type": "concept", "title": "Diversion"}], "description": "Most cases are resolved before trial, so pretrial decisions shape justice outcomes."}, {"id": "43f5d4db-b072-4049-9bd5-d0ed7203b557", "type": "subtopic", "title": "Trials and sentencing", "children": [{"id": "fbe4313c-4832-4ca5-a97d-a5e349fa57fc", "type": "concept", "title": "Jury selection"}, {"id": "27e2b4c9-2469-411d-b8af-dc6a4b44ab61", "type": "concept", "title": "Evidence and witnesses"}, {"id": "e14fc07c-57a4-41e3-bfa4-422e7e29a29f", "type": "concept", "title": "Verdicts"}, {"id": "ba133423-2c15-4b2b-9bd4-dff05ea16245", "type": "concept", "title": "Sentencing hearings"}], "description": "Trials are central to constitutional ideals even when rare, and sentencing determines the formal consequence."}]}, {"id": "877bfc72-0356-4be8-b906-109ab7136483", "type": "topic", "title": "Corrections, Reentry, and Community Supervision", "description": "Understand punishment and correctional practice across jails, prisons, probation, parole, treatment, and reentry.", "children": [{"id": "92f5289c-7c0e-4396-a3cc-bd9d32b44c6c", "type": "subtopic", "title": "Jails and prisons", "children": [{"id": "c42e3e0b-6c76-45d5-9726-9be13e712f81", "type": "concept", "title": "Jails"}, {"id": "5a3630f4-52f7-42c6-8e8a-2dca733bbea6", "type": "concept", "title": "State prisons"}, {"id": "08a37e55-91d5-40e7-872a-7e0bcbd1443f", "type": "concept", "title": "Federal prisons"}, {"id": "cd16be1d-130f-4553-80aa-95de298739ed", "type": "concept", "title": "Private and contracted facilities"}], "description": "Confinement institutions differ in purpose, population, governance, and daily conditions."}, {"id": "50cbfdf0-bfeb-443c-a616-958ee02e17d5", "type": "subtopic", "title": "Community corrections", "children": [{"id": "e25148f5-f7a8-4243-bd8a-2f158474b004", "type": "concept", "title": "Probation"}, {"id": "ef6e8957-9bc2-43b2-982e-de3c2812fa2e", "type": "concept", "title": "Parole"}, {"id": "edfd1bf6-fd00-4895-8660-df8fad297cf8", "type": "concept", "title": "Intermediate sanctions"}, {"id": "78d57cf4-f0df-4af9-b45e-8e179ca667df", "type": "concept", "title": "Electronic monitoring"}], "description": "Most correctional control occurs in communities rather than behind prison walls."}, {"id": "8d7769ad-573a-4822-90b4-59011ab64f33", "type": "subtopic", "title": "Reentry and rehabilitation", "children": [{"id": "40bdfb2a-d9d7-4098-a81d-c15b5c0f377b", "type": "concept", "title": "Risk-needs-responsivity"}, {"id": "02e2d9f2-f444-4b34-b8db-ed1488cc7576", "type": "concept", "title": "Education and treatment"}, {"id": "4084fbbb-5df7-444b-9fd0-458d48e0d47a", "type": "concept", "title": "Collateral consequences"}, {"id": "88454b5d-582f-4027-b193-a2c623b3f5c4", "type": "concept", "title": "Desistance"}], "description": "Reentry connects punishment to housing, employment, treatment, family, supervision, and public safety."}]}, {"id": "bcedbb0b-d736-4d61-801f-78cbd1b3aa89", "type": "topic", "title": "Victims, Victimology, and Harm", "description": "Center crime victims, survivors, communities, trauma, rights, services, and the many forms of harm produced by crime and justice responses.", "children": [{"id": "68aa07bd-ec02-442f-bc46-2242d7c7bfd8", "type": "subtopic", "title": "Victimization patterns", "children": [{"id": "29785a29-25ab-4ec9-b4f5-d164fe3309cf", "type": "concept", "title": "Violent victimization"}, {"id": "f04a6398-60bf-4487-bcd3-5624a935564e", "type": "concept", "title": "Property victimization"}, {"id": "1f11c08f-7f23-42b3-836f-d8972d9bcd9d", "type": "concept", "title": "Repeat victimization"}, {"id": "9604f4df-9ac5-46e0-a4a4-b831121af7fd", "type": "concept", "title": "Vulnerable populations"}], "description": "Victimology helps students understand who is harmed, by what, and under what social conditions."}, {"id": "1aec5ac6-2756-41c9-9d04-39727844ac43", "type": "subtopic", "title": "Victim rights and services", "children": [{"id": "cba015af-dcdb-4f5c-a7f2-76a96ee2f68b", "type": "concept", "title": "Notification"}, {"id": "ad9c89b1-302f-4a53-ace0-055d18402d86", "type": "concept", "title": "Victim impact statements"}, {"id": "e797ef88-adc5-4883-af3e-b2b779473e0f", "type": "concept", "title": "Restitution"}, {"id": "f1577b2d-7742-4e04-957c-f96edc4af2c0", "type": "concept", "title": "Advocacy and compensation"}], "description": "Modern criminal justice includes formal victim participation and support systems."}, {"id": "6b469849-3134-4bda-9116-3d289ef8f9bf", "type": "subtopic", "title": "Trauma and community harm", "children": [{"id": "2e58d6de-d3df-4edf-9c88-4f34bc3489ed", "type": "concept", "title": "Trauma-informed practice"}, {"id": "c9881e2c-e8a9-48a4-8e48-e7d331fa1a07", "type": "concept", "title": "Secondary victimization"}, {"id": "e0bcc7c2-ef0b-4b69-9f27-eefb56b43380", "type": "concept", "title": "Community violence"}, {"id": "74b40161-0adf-4609-a5b2-555defb21ca6", "type": "concept", "title": "Restorative justice"}], "description": "Crime can harm people, families, neighborhoods, and institutions beyond the immediate offense."}]}, {"id": "d3028ff4-4fdc-4dd4-bbdf-c4f90ddfbafd", "type": "topic", "title": "Juvenile Justice and Youth Development", "description": "Examine youth offending, adolescent development, juvenile courts, schools, diversion, detention, and rehabilitation.", "children": [{"id": "715f370d-c88e-4bf2-8cf9-4cd1c86337fd", "type": "subtopic", "title": "Youth development", "children": [{"id": "747471b8-ea34-4fb6-9e53-7440befb5d7a", "type": "concept", "title": "Brain development"}, {"id": "97e67a4c-9ded-426a-90e4-96b17907b753", "type": "concept", "title": "Peer influence"}, {"id": "520867c4-a843-42d3-9a70-96b0a773c3c6", "type": "concept", "title": "Family and school context"}, {"id": "c8f25bec-a31c-4076-8d3c-7b4f6d4f94e4", "type": "concept", "title": "Protective factors"}], "description": "Adolescent development changes how students should think about culpability, deterrence, and rehabilitation."}, {"id": "4b5c07d6-09ba-4198-9e9f-5c7bc95ff53b", "type": "subtopic", "title": "Juvenile court process", "children": [{"id": "6c1cff53-d6bb-4b23-ac83-15cc06ec1b62", "type": "concept", "title": "Intake"}, {"id": "227386b0-b28e-4137-954a-29624416e884", "type": "concept", "title": "Adjudication"}, {"id": "50c400ce-4c6d-4a4f-9a4f-759223b0bfda", "type": "concept", "title": "Disposition"}, {"id": "c4c5a429-7db5-4855-9616-581b1d839ea5", "type": "concept", "title": "Transfer to adult court"}], "description": "Juvenile justice has distinct procedures, vocabulary, and goals."}, {"id": "029e2679-4821-4457-b6b3-d9c1a92fc3c2", "type": "subtopic", "title": "Prevention and intervention", "children": [{"id": "5fa3f207-a370-4fcc-9270-189bf9a3b997", "type": "concept", "title": "Diversion"}, {"id": "66bf98c8-36ac-4bb3-a9f9-e02620e2b62d", "type": "concept", "title": "School discipline"}, {"id": "e67a4c11-8501-43f7-8cc1-778bc7ebf554", "type": "concept", "title": "Detention alternatives"}, {"id": "c85a711d-0acd-4d6d-bebd-dab1fb1422f4", "type": "concept", "title": "Evidence-based programs"}], "description": "Youth justice works best when connected to schools, families, services, and community supports."}]}, {"id": "99025641-298c-4b12-8a31-8fda0e366293", "type": "topic", "title": "Race, Class, Gender, and Inequality in Criminal Justice", "description": "Analyze how social inequality shapes exposure to crime, system contact, legal outcomes, punishment, and trust.", "children": [{"id": "ea7144cb-08b7-4e56-830e-0857797729ee", "type": "subtopic", "title": "Disparities across decision points", "children": [{"id": "2189d082-07a9-4d0b-b6d4-83a379f64fda", "type": "concept", "title": "Race and ethnicity"}, {"id": "a921c3dc-ad77-44c9-ad66-7b6bb597706b", "type": "concept", "title": "Poverty and wealth"}, {"id": "9185354c-eb02-4414-9fd9-07746c2d4cab", "type": "concept", "title": "Gender and sexuality"}, {"id": "ed03cd6a-ca02-4772-8af9-012a72ab37e1", "type": "concept", "title": "Disability and mental health"}], "description": "Inequality can enter through exposure, enforcement, charging, bail, plea bargaining, sentencing, and supervision."}, {"id": "491d865d-2e86-4d12-93d7-d47c07151d58", "type": "subtopic", "title": "Mass incarceration and collateral consequences", "children": [{"id": "6f7f3d2d-eef6-4ca9-bf49-e73eb3839862", "type": "concept", "title": "Incarceration rates"}, {"id": "a2447eb5-7413-4d4e-a26a-da238b136dc1", "type": "concept", "title": "Fines and fees"}, {"id": "6ad44f58-cae9-4773-b1e1-3f790dbf531c", "type": "concept", "title": "Housing and employment barriers"}, {"id": "bb57dfc0-6641-4a4f-81df-8a2ae0bb67ec", "type": "concept", "title": "Family impact"}], "description": "Punishment affects families, neighborhoods, labor markets, voting rights, and civic life."}, {"id": "5adbb628-a865-4368-b376-b36676bf78a2", "type": "subtopic", "title": "Legitimacy and trust", "children": [{"id": "e74debeb-fce7-4fd1-87c1-33db3b0ab788", "type": "concept", "title": "Procedural justice"}, {"id": "8666cd51-a75d-4ef7-9f18-bd99a39a758d", "type": "concept", "title": "Legal cynicism"}, {"id": "b7eece4b-406f-404e-b588-5f9d1c4a6647", "type": "concept", "title": "Community trust"}, {"id": "fbf09a4e-e929-4eb3-b019-24e155764537", "type": "concept", "title": "Transparency"}], "description": "People's experiences with justice institutions shape cooperation, compliance, and democratic legitimacy."}]}, {"id": "194ce965-9a5c-4487-904b-d8315ad8732a", "type": "topic", "title": "Criminal Justice Policy, Politics, and Governance", "description": "Learn how criminal justice policy is made, implemented, evaluated, funded, contested, and reformed.", "children": [{"id": "613c5de8-76ae-41a1-ae3a-1928bba88c50", "type": "subtopic", "title": "Policy actors", "children": [{"id": "33987f48-f405-438b-b0a4-df134943d656", "type": "concept", "title": "Legislatures"}, {"id": "d5f2fdd5-07a2-4c38-95ee-4bae60707570", "type": "concept", "title": "Executives"}, {"id": "55859d2b-446d-4d5d-9db4-2fd8f19c1277", "type": "concept", "title": "Courts"}, {"id": "49e01aa0-13ad-4187-99c8-fe5a143aad5b", "type": "concept", "title": "Advocacy organizations"}], "description": "Justice policy is shaped by officials, agencies, courts, communities, interest groups, and budgets."}, {"id": "e6758d80-c5ac-4cf7-af30-db5c4163fb9b", "type": "subtopic", "title": "Policy tools", "children": [{"id": "03b861da-d367-4d7c-ad66-62448735b548", "type": "concept", "title": "Statutes"}, {"id": "5c24a86b-46c6-4952-962b-5514da744210", "type": "concept", "title": "Grants"}, {"id": "4ddf32c4-59b5-485b-a705-9ab361a006eb", "type": "concept", "title": "Guidelines"}, {"id": "79a8005f-cf45-4194-877b-bd575626e818", "type": "concept", "title": "Administrative rules"}], "description": "Policies use law, funding, training, data, supervision, sanctions, services, and organizational incentives."}, {"id": "361c2de8-c6ab-4a58-9dc7-c276ac2895f4", "type": "subtopic", "title": "Policy analysis basics", "children": [{"id": "cfd2d498-8c67-4bd8-9c3f-2d2c7605e9b5", "type": "concept", "title": "Problem definition"}, {"id": "34b9b146-b740-4dc3-a5ea-48a0638d414f", "type": "concept", "title": "Stakeholder analysis"}, {"id": "382c368a-c2cb-41aa-844c-8f84d19687ed", "type": "concept", "title": "Costs and benefits"}, {"id": "326f5a1e-492b-4be5-b682-17236c063c5e", "type": "concept", "title": "Implementation barriers"}], "description": "Students learn to ask whether a policy is lawful, effective, equitable, feasible, and accountable."}]}, {"id": "c36308f9-d1e5-4c57-957b-6cf8b2a10966", "type": "topic", "title": "Ethics, Professionalism, and Discretion", "description": "Practice ethical reasoning for decisions made by police, prosecutors, defense counsel, judges, correctional staff, analysts, and leaders.", "children": [{"id": "bdd994ab-0655-4b89-a85b-20bc388f60bf", "type": "subtopic", "title": "Discretion in practice", "children": [{"id": "b144a4d6-61c8-497a-ac7c-72469dd762cf", "type": "concept", "title": "Police discretion"}, {"id": "7ab68805-b29c-40d3-ad49-d012c1d261c0", "type": "concept", "title": "Prosecutorial discretion"}, {"id": "35b69054-eebe-4c9a-8d79-fcfa51b21a30", "type": "concept", "title": "Judicial discretion"}, {"id": "d8383d52-3c07-4984-8319-1554bfac8eff", "type": "concept", "title": "Correctional discretion"}], "description": "Discretion is unavoidable in justice work, so students must learn how it can be guided or abused."}, {"id": "9cb72234-612b-43f1-b3d1-c0acf95e9210", "type": "subtopic", "title": "Ethical decision-making", "children": [{"id": "25cf2c00-6f3c-4c3c-8611-8d3cef867292", "type": "concept", "title": "Conflicts of interest"}, {"id": "8369bb64-e807-43b3-b5df-f75c02b7615d", "type": "concept", "title": "Truthfulness"}, {"id": "3bf3da80-05de-4316-986e-68926df42764", "type": "concept", "title": "Confidentiality"}, {"id": "12dbf73f-cbc0-470d-a0aa-8bd5052eb2af", "type": "concept", "title": "Misconduct reporting"}], "description": "Ethics gives students a framework for conflicts among law, loyalty, safety, fairness, and human dignity."}, {"id": "f618d42d-5806-40c6-9464-9b436dc21852", "type": "subtopic", "title": "Professional identity", "children": [{"id": "63489a75-c677-4999-a4f7-df63ed75d5af", "type": "concept", "title": "Public service values"}, {"id": "a184e4e7-7a83-4ad4-85c2-62463446b71c", "type": "concept", "title": "Bias awareness"}, {"id": "269413e0-e319-47f6-b849-9201473074fa", "type": "concept", "title": "Documentation"}, {"id": "a8a36c5d-bf8a-408b-a381-3577dbd17af1", "type": "concept", "title": "Respectful communication"}], "description": "Criminal justice careers require habits of accountability, cultural competence, communication, and restraint."}]}, {"id": "34f6caf8-ec1a-4ef6-9048-3db2a3b5360e", "type": "topic", "title": "Evidence, Forensic Science, and Investigation Basics", "description": "Introduce evidence, scientific investigation, forensic limits, chain of custody, eyewitness evidence, and investigative reasoning.", "children": [{"id": "bd3c7cc3-870f-42c3-8a2e-ed9e4d5549ce", "type": "subtopic", "title": "Investigation fundamentals", "children": [{"id": "b4f777ae-e95b-43a8-9d6a-90319c6c2ac1", "type": "concept", "title": "Crime scenes"}, {"id": "540b5dd9-f453-4790-9345-00fbc2d42922", "type": "concept", "title": "Witness interviews"}, {"id": "1aa19e61-6886-44c2-ac8e-12f673c6fccc", "type": "concept", "title": "Reports"}, {"id": "8fcdfab8-8578-4f72-aa40-469af6cf5e57", "type": "concept", "title": "Probable cause"}], "description": "Investigations turn information into evidence through interviews, records, observation, and analysis."}, {"id": "72a0bc9b-5f9b-433e-b474-281586d3d027", "type": "subtopic", "title": "Forensic science literacy", "children": [{"id": "5a08d92a-1f5a-4dd9-af24-bc4d185a86ab", "type": "concept", "title": "DNA"}, {"id": "b12ac601-7892-41e3-8f6b-38844e6d2891", "type": "concept", "title": "Fingerprints"}, {"id": "ca881fe5-e61b-4d54-a447-79be729067be", "type": "concept", "title": "Toxicology"}, {"id": "f26f57a6-70bc-4030-adce-cdf8787d5c45", "type": "concept", "title": "Firearms and trace evidence"}], "description": "Students need enough forens